with valid as (select *, floor(temp_c) as temp_c_whole from device_readings where status_bits < 10), metrics as (select id, device_code, pressure, firmware, temp_c_whole, cume_dist() over (partition by device_code order by temp_c nulls last) as temp_c_cume_dist, percent_rank() over (partition by device_code order by temp_c_whole desc) as temp_c_whole_percent_rank, avg(temp_c) over (partition by device_code order by humidity, id rows between 5 preceding and 1 preceding) as temp_c_avg_5_prior, min(pressure) over (partition by device_code) as device_code_min_pressure, lead(pressure, 2) over (partition by device_code order by humidity, id) as next_pressure from valid), filtered as (select *, device_code_min_pressure * temp_c_whole as device_code_min_pressure_times_temp_c_whole, upper(firmware) as firmware_upper from metrics where temp_c_whole_percent_rank <= 0.69), ranked as (select id, pressure, temp_c_cume_dist, temp_c_avg_5_prior, device_code_min_pressure, next_pressure, device_code_min_pressure_times_temp_c_whole from (select *, row_number() over (partition by device_code order by next_pressure, id) as dedup_rank from filtered) x where dedup_rank = 1), cleaned as (select id, pressure, temp_c_avg_5_prior, device_code_min_pressure, next_pressure, device_code_min_pressure_times_temp_c_whole, cast(device_code_min_pressure as double) as device_code_min_pressure_num, round(device_code_min_pressure_times_temp_c_whole / device_code_min_pressure, 2) as device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure from ranked where temp_c_cume_dist <= 0.24), metrics_device_readings as (select id, temp_c_avg_5_prior, next_pressure, device_code_min_pressure_times_temp_c_whole, device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure, lag(next_pressure) over (order by next_pressure, id) as prev_next_pressure, lead(next_pressure) over (order by next_pressure, id) as next_next_pressure, lead(device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure) over (order by next_pressure, id) as next_device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure, lag(device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure) over (order by next_pressure, id) as prev_device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure, row_number() over (order by next_pressure, id) as seq_no, first_value(device_code_min_pressure) ignore nulls over (order by temp_c_avg_5_prior, id rows between unbounded preceding and current row) as first_known_device_code_min_pressure from cleaned) select seq_no, max(first_known_device_code_min_pressure) as max_first_known_device_code_min_pressure, percentile_approx(device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure, 0.5) as device_code_min_pressure_times_temp_c_whole_per_device_code_min_pressure_p50, count(distinct id) as distinct_ids, round(avg(temp_c_avg_5_prior), 2) as avg_temp_c_avg_5_prior from metrics_device_readings group by seq_no;
